     1→/**
     2→ * Image Generation Service
     3→ * Client for OpenRouter API using Gemini 2.5 Flash Preview Image model for outfit visualization
     4→ *
     5→ * Features:
     6→ * - Fashion-specific prompt engineering
     7→ * - Error handling with retries
     8→ * - Timeout protection
     9→ * - Rate limiting awareness
    10→ */
    11→
    12→import type { ImageGenerationRequest, ImageGenerationResponse } from '../types/image-types';
    13→
    14→/**
    15→ * OpenRouter API configuration
    16→ */
    17→const OPENROUTER_CONFIG = {
    18→  /** OpenRouter API base URL */
    19→  baseUrl: 'https://openrouter.ai/api/v1',
    20→  /**
    21→   * Model ID for Gemini 3 Pro Image Preview - Nano Banana Pro (text-to-image capable)
    22→   * Google's most advanced image-generation and editing model
    23→   */
    24→  model: 'google/gemini-2.5-flash-image',
    25→  /** Request timeout in milliseconds */
    26→  timeout: 30000,
    27→  /** Maximum retry attempts on failure */
    28→  maxRetries: 2,
    29→  /** Exponential backoff base delay (ms) */
    30→  retryDelay: 1000,
    31→};
    32→
    33→/**
    34→ * OpenRouter Image Generation Client
    35→ * Handles communication with OpenRouter API for outfit image generation
    36→ */
    37→export class OpenRouterImageClient {
    38→  private apiKey: string;
    39→  private requestCount: number = 0;
    40→  private lastRequestTime: number = 0;
    41→
    42→  /**
    43→   * Creates a new OpenRouter image client
    44→   *
    45→   * @param apiKey - OpenRouter API key
    46→   * @throws Error if API key is not provided
    47→   */
    48→  constructor(apiKey: string) {
    49→    if (!apiKey || typeof apiKey !== 'string' || apiKey.trim() === '') {
    50→      throw new Error('OpenRouter API key is required');
    51→    }
    52→    this.apiKey = apiKey;
    53→  }
    54→
    55→  /**
    56→   * Generates an outfit image from description using Gemini 2.5 Flash Preview
    57→   *
    58→   * @param description - Outfit description extracted from conversation
    59→   * @param options - Optional style parameters
    60→   * @returns Promise resolving to image generation response
    61→   *
    62→   * @example
    63→   * const client = new OpenRouterImageClient(apiKey);
    64→   * const response = await client.generateOutfitImage(
    65→   *   "White shirt with black pants for business meeting",
    66→   *   { style: { composition: 'flat-lay' } }
    67→   * );
    68→   */
    69→  async generateOutfitImage(
    70→    description: string,
    71→    options?: ImageGenerationRequest['style']
    72→  ): Promise<ImageGenerationResponse> {
    73→    // Validate input
    74→    if (!description || typeof description !== 'string' || description.trim() === '') {
    75→      return {
    76→        success: false,
    77→        error: 'INVALID_DESCRIPTION',
    78→        message: 'Outfit description is required',
    79→      };
    80→    }
    81→
    82→    // Check client-side rate limiting (basic protection)
    83→    if (!this.checkRateLimit()) {
    84→      return {
    85→        success: false,
    86→        error: 'RATE_LIMITED',
    87→        message: 'Too many requests. Please wait a moment before trying again.',
    88→      };
    89→    }
    90→
    91→    // Attempt generation with retries
    92→    let lastError: Error | null = null;
    93→
    94→    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
    95→      try {
    96→        if (attempt > 0) {
    97→          // Exponential backoff delay
    98→          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
    99→          await this.sleep(delay);
   100→          console.log(`[ImageGen] Retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
   101→        }
   102→
   103→        const result = await this.makeRequest(description, options);
   104→        return result;
   105→      } catch (error) {
   106→        lastError = error as Error;
   107→        console.error(`[ImageGen] Attempt ${attempt + 1} failed:`, error);
   108→
   109→        // Don't retry on certain errors
   110→        if (this.isNonRetryableError(error)) {
   111→          break;
   112→        }
   113→      }
   114→    }
   115→
   116→    // All retries failed
   117→    return {
   118→      success: false,
   119→      error: 'GENERATION_FAILED',
   120→      message: 'Unable to generate image. Please try again later.',
   121→    };
   122→  }
   123→
   124→  /**
   125→   * Makes the actual API request to OpenRouter
   126→   *
   127→   * @private
   128→   */
   129→  private async makeRequest(
   130→    description: string,
   131→    options?: ImageGenerationRequest['style']
   132→  ): Promise<ImageGenerationResponse> {
   133→    // Build fashion-specific prompt
   134→    const prompt = this.buildFashionPrompt(description, options);
   135→
   136→    // Create request payload - OpenRouter image generation requires messages format with modalities
   137→    const requestBody = {
   138→      model: OPENROUTER_CONFIG.model,
   139→      messages: [
   140→        {
   141→          role: 'user',
   142→          content: prompt,
   143→        },
   144→      ],
   145→      modalities: ['text', 'image'], // Required for image generation
   146→      max_tokens: 4096, // For image generation
   147→    };
   148→
   149→    console.log('[ImageGen] Sending request to OpenRouter:', {
   150→      model: requestBody.model,
   151→      promptLength: prompt.length,
   152→    });
   153→
   154→    // Create abort controller for timeout
   155→    const controller = new AbortController();
   156→    const timeoutId = setTimeout(() => controller.abort(), OPENROUTER_CONFIG.timeout);
   157→
   158→    try {
   159→      const response = await fetch(`${OPENROUTER_CONFIG.baseUrl}/chat/completions`, {
   160→        method: 'POST',
   161→        headers: {
   162→          'Content-Type': 'application/json',
   163→          Authorization: `Bearer ${this.apiKey}`,
   164→          'HTTP-Referer': 'https://ootday.com', // Optional: Your site URL
   165→          'X-Title': 'OOTDay Fashion Assistant', // Optional: Your app name
   166→        },
   167→        body: JSON.stringify(requestBody),
   168→        signal: controller.signal,
   169→      });
   170→
   171→      clearTimeout(timeoutId);
   172→
   173→      if (!response.ok) {
   174→        const errorData = await response.json().catch(() => ({}));
   175→        throw new Error(
   176→          `OpenRouter API error: ${response.status} - ${errorData.error?.message || response.statusText}`
   177→        );
   178→      }
   179→
   180→      const data = await response.json();
   181→
   182→      // Parse response and extract image
   183→      // Note: Gemini 2.5 Flash Preview returns image as base64 in content
   184→      const imageData = this.parseImageResponse(data);
   185→
   186→      return {
   187→        success: true,
   188→        imageBase64: imageData.base64,
   189→        imageUrl: imageData.url,
   190→        metadata: {
   191→          model: OPENROUTER_CONFIG.model,
   192→          generatedAt: new Date().toISOString(),
   193→          prompt: prompt,
   194→        },
   195→        message: 'Image generated successfully',
   196→      };
   197→    } catch (error) {
   198→      clearTimeout(timeoutId);
   199→
   200→      if (error instanceof Error) {
   201→        if (error.name === 'AbortError') {
   202→          throw new Error('Request timeout - image generation took too long');
   203→        }
   204→        throw error;
   205→      }
   206→
   207→      throw new Error('Unknown error during image generation');
   208→    }
   209→  }
   210→
   211→  /**
   212→   * Builds fashion-specific prompt for image generation
   213→   * Applies professional photography style and Thai fashion aesthetic
   214→   *
   215→   * @private
   216→   */
   217→  private buildFashionPrompt(
   218→    description: string,
   219→    options?: ImageGenerationRequest['style']
   220→  ): string {
   221→    const photographyStyle = options?.photographyStyle || 'editorial fashion';
   222→    const composition = options?.composition || 'full-body model shoot';
   223→    const lighting = options?.lighting || 'studio';
   224→    const aesthetic = options?.aestheticContext || 'modern international';
   225→
   226→    // Fashion-specific prompt template
   227→    const promptTemplate = `
   228→Generate a high-quality fashion photograph of a real person wearing the outfit:
   229→
   230→OUTFIT DESCRIPTION: ${description}
   231→
   232→PHOTOGRAPHY STYLE: ${photographyStyle}
   233→COMPOSITION: ${composition}
   234→LIGHTING: ${lighting}
   235→AESTHETIC: ${aesthetic} fashion style
   236→
   237→REQUIREMENTS:
   238→- Professional product photography quality
   239→- Clear, well-lit composition
   240→- Clean background (white or minimal)
   241→- Sharp focus on outfit details
   242→- Accurate color representation
   243→- Suitable for fashion e-commerce
   244→- Thai contemporary fashion aesthetic
   245→- Elegant and modern presentation
   246→
   247→AVOID:
   248→- Blurry or low-resolution images
   249→- Cluttered backgrounds
   250→- Poor lighting or shadows
   251→- Distorted proportions
   252→- Unrealistic colors
   253→`.trim();
   254→
   255→    return promptTemplate;
   256→  }
   257→
   258→  /**
   259→   * Parses image response from OpenRouter API
   260→   * OpenRouter returns images in an 'images' array within the assistant message
   261→   *
   262→   * @private
   263→   */
   264→  private parseImageResponse(data: any): { base64?: string; url?: string } {
   265→    // OpenRouter returns images as base64 data URLs in the 'images' array
   266→    // Format: { choices: [{ message: { content: "...", images: ["data:image/png;base64,..."] } }] }
   267→
   268→    try {
   269→      console.log('[ImageGen] Parsing response:', JSON.stringify(data).slice(0, 500));
   270→
   271→      if (data.choices && data.choices[0] && data.choices[0].message) {
   272→        const message = data.choices[0].message;
   273→
   274→        // Primary format: images array (OpenRouter standard)
   275→        if (message.images && Array.isArray(message.images) && message.images.length > 0) {
   276→          const imageData = message.images[0];
   277→          console.log('[ImageGen] Found image in images array, type:', typeof imageData);
   278→
   279→          // Images are returned as data URLs (data:image/png;base64,...)
   280→          if (typeof imageData === 'string' && imageData.startsWith('data:image')) {
   281→            return { base64: imageData };
   282→          }
   283→
   284→          // Or as object with nested structure: {"type":"image_url","image_url":{"url":"data:..."}}
   285→          if (typeof imageData === 'object') {
   286→            // Check for image_url.url format (OpenRouter Gemini format)
   287→            if (imageData.image_url?.url) {
   288→              console.log('[ImageGen] Found image in image_url.url format');
   289→              const url = imageData.image_url.url;
   290→              if (url.startsWith('data:image')) {
   291→                return { base64: url };
   292→              }
   293→              return { url };
   294→            }
   295→            // Check for b64_json format
   296→            if (imageData.b64_json) {
   297→              return { base64: `data:image/png;base64,${imageData.b64_json}` };
   298→            }
   299→            // Check for direct base64/url
   300→            if (imageData.base64) {
   301→              return { base64: imageData.base64.startsWith('data:') ? imageData.base64 : `data:image/png;base64,${imageData.base64}` };
   302→            }
   303→            if (imageData.url) {
   304→              return { url: imageData.url };
   305→            }
   306→          }
   307→        }
   308→
   309→        // Check content for embedded base64 or URLs
   310→        const content = message.content;
   311→        if (typeof content === 'string') {
   312→          // Check if content contains base64 image data
   313→          const base64Match = content.match(/data:image\/(png|jpeg|jpg|webp);base64,[A-Za-z0-9+/=]+/);
   314→          if (base64Match) {
   315→            console.log('[ImageGen] Found base64 image in content');
   316→            return { base64: base64Match[0] };
   317→          }
   318→
   319→          // Check for URL in content
   320→          const urlMatch = content.match(/(https?:\/\/[^\s<>"]+\.(png|jpg|jpeg|gif|webp))/i);
   321→          if (urlMatch) {
   322→            console.log('[ImageGen] Found URL in content');
   323→            return { url: urlMatch[0] };
   324→          }
   325→        }
   326→
   327→        // Check for structured image data (fallback)
   328→        if (message.image) {
   329→          console.log('[ImageGen] Found image in message.image');
   330→          return {
   331→            base64: message.image.base64 || (message.image.b64_json ? `data:image/png;base64,${message.image.b64_json}` : undefined),
   332→            url: message.image.url,
   333→          };
   334→        }
   335→      }
   336→
   337→      // Fallback: return empty (will need to handle in caller)
   338→      console.warn('[ImageGen] Could not parse image from response. Keys:', Object.keys(data));
   339→      if (data.choices?.[0]?.message) {
   340→        console.warn('[ImageGen] Message keys:', Object.keys(data.choices[0].message));
   341→      }
   342→      return {};
   343→    } catch (error) {
   344→      console.error('[ImageGen] Error parsing image response:', error);
   345→      return {};
   346→    }
   347→  }
   348→
   349→  /**
   350→   * Client-side rate limiting check
   351→   * Limits to approximately 10 requests per minute
   352→   *
   353→   * @private
   354→   */
   355→  private checkRateLimit(): boolean {
   356→    const now = Date.now();
   357→    const minuteAgo = now - 60000;
   358→
   359→    // Reset counter if a minute has passed
   360→    if (this.lastRequestTime < minuteAgo) {
   361→      this.requestCount = 0;
   362→    }
   363→
   364→    // Check if under limit
   365→    if (this.requestCount >= 10) {
   366→      return false;
   367→    }
   368→
   369→    // Update counters
   370→    this.requestCount++;
   371→    this.lastRequestTime = now;
   372→
   373→    return true;
   374→  }
   375→
   376→  /**
   377→   * Checks if error is non-retryable (auth, validation, etc.)
   378→   *
   379→   * @private
   380→   */
   381→  private isNonRetryableError(error: any): boolean {
   382→    if (!error) return false;
   383→
   384→    const errorMessage = error.message || error.toString();
   385→
   386→    // Don't retry authentication errors
   387→    if (errorMessage.includes('401') || errorMessage.includes('403')) {
   388→      return true;
   389→    }
   390→
   391→    // Don't retry validation errors
   392→    if (errorMessage.includes('400') || errorMessage.includes('INVALID')) {
   393→      return true;
   394→    }
   395→
   396→    // Don't retry rate limit errors (need to wait)
   397→    if (errorMessage.includes('429') || errorMessage.includes('RATE_LIMIT')) {
   398→      return true;
   399→    }
   400→
   401→    return false;
   402→  }
   403→
   404→  /**
   405→   * Sleep utility for retry delays
   406→   *
   407→   * @private
   408→   */
   409→  private sleep(ms: number): Promise<void> {
   410→    return new Promise((resolve) => setTimeout(resolve, ms));
   411→  }
   412→}
   413→
   414→/**
   415→ * Creates a new OpenRouter image client with API key from environment
   416→ *
   417→ * @returns OpenRouterImageClient instance or null if API key not available
   418→ *
   419→ * @example
   420→ * const client = createImageClient();
   421→ * if (client) {
   422→ *   const response = await client.generateOutfitImage(description);
   423→ * }
   424→ */
   425→export function createImageClient(): OpenRouterImageClient | null {
   426→  const apiKey = process.env.OPENROUTER_API_KEY;
   427→
   428→  if (!apiKey) {
   429→    console.warn('[ImageGen] OPENROUTER_API_KEY not found in environment');
   430→    return null;
   431→  }
   432→
   433→  try {
   434→    return new OpenRouterImageClient(apiKey);
   435→  } catch (error) {
   436→    console.error('[ImageGen] Failed to create image client:', error);
   437→    return null;
   438→  }
   439→}
   440→

