/**
 * Fitting Model Generation Service
 * Generates AI-powered fitting model images using the user's uploaded photo
 *
 * Features:
 * - Photorealistic fitting model generation from user photo
 * - Mystery mode for users who don't upload photos
 * - Standard outfit: white crop top + black shorts + barefoot
 */

/**
 * Response from fitting model generation
 */
export interface FittingModelResponse {
  success: boolean;
  imageUrl?: string;
  imageBase64?: string;
  error?: string;
  message?: string;
}

/**
 * Fitting model prompt template based on fitting_model.md
 * Generates a person in standard outfit (white crop top + black shorts + barefoot)
 */
const FITTING_MODEL_PROMPT_TEMPLATE = `
Create a photorealistic fitting model showing a person with the following characteristics:

FACIAL ACCURACY:
The face MUST be an EXACT photorealistic match to the person in the uploaded image. This is the absolute highest priority. The generated face should be immediately recognizable as the same person to anyone familiar with them. Preserve ALL unique and distinctive facial characteristics without modification, idealization, or beautification.

PERSON CHARACTERISTICS (from uploaded photo):
Face: MUST be accurately an EXACT photorealistic match to the person in the uploaded image.
Facial Structure: Exact bone structure including cheekbones, jawline shape, chin shape, forehead shape, and overall face shape
Eyes: Precise eye shape, size, color, iris patterns, spacing between eyes, eye opening, eyelid characteristics, eyebrow shape, thickness, arch, and positioning
Nose: Accurate nose shape, bridge height and width, nostril size and shape, nose tip characteristics, nose-to-face proportions
Mouth & Lips: Exact mouth width, lip fullness, lip shape, cupid's bow definition, smile characteristics, mouth-to-face proportions
Skin Tone: EXACT skin tone match including all undertones, overtones, color variations across face - preserve ethnic and regional facial characteristics
Skin Texture: Natural skin texture with all visible characteristics - freckles, beauty marks, moles, birthmarks, pores, fine lines, age-appropriate features
Hair: Exact hair color (including highlights, lowlights, natural variations), precise hairstyle, hair texture (straight/wavy/curly/coily), hair volume, density, flow, hairline shape and position
Distinguishing Features: ANY unique facial characteristics (dimples, facial asymmetry, scars, distinctive features) MUST be preserved exactly
Body type and Height appearance: match the person in the source image. If only a face or portrait is provided, generate a model with standard proportions appropriate to the person's apparent age and build
Skin tone: Match exactly to reference image
Age appearance: Maintain age-appropriate facial features accurately - do not age up or down

SETTING & CONTEXT:
Location: indoor
Lighting: Natural, soft, professional studio lighting
Background: Clean, minimal, white backdrop

Outfit:
Top: White spaghetti strap crop top
Bottom: Black high-waisted legging shorts
Footwear: No shoes - barefoot

Pose detail:
Stance: Standing perfectly straight, facing directly forward toward camera with body centered
Body Alignment: Fully symmetrical - shoulders level and square, hips aligned, spine completely straight and elongated
Arms: Hanging straight down along the sides of the body, completely relaxed with natural arm position
Hands: Relaxed at sides with fingers gently extended naturally, no tension
Legs: Standing with feet close together (nearly touching or lightly touching), legs straight and aligned
Weight Distribution: Evenly distributed on both feet - no hip shift or weight lean
Head Position: Facing directly forward, eye-level gaze straight to camera, chin level, neck elongated
Shoulders: Relaxed downward but slightly back for clean posture, not hunched
Overall Posture: Professional catalog pose - clean, symmetrical, perfectly upright positioning ideal for garment visualization and virtual try-on applications

QUALITY REQUIREMENTS:
Resolution: High-resolution for maximum detail and quality
Photo quality: Professional photography standard
Realism: 100% photorealistic
Face preservation: 100% similarity to original photo
Lighting: Consistent with environment
Shadows and draping: Natural fabric behavior and realistic shadows
Color accuracy: True to actual product color
`.trim();

/**
 * Mystery mode prompt template for users who don't upload photos
 */
const MYSTERY_MODEL_PROMPT = `
Create a photorealistic fitting model showing an anonymous Thai woman with the following characteristics:

PERSON CHARACTERISTICS:
Face: Beautiful, friendly Thai woman with natural features, age approximately 25-30
Facial Structure: Soft, symmetrical features with natural Thai characteristics
Eyes: Warm brown eyes, natural eye shape typical of Southeast Asian features
Skin Tone: Natural Thai skin tone, warm undertones
Hair: Black or dark brown, shoulder-length, straight to slightly wavy, well-groomed
Body Type: Healthy, proportionate figure suitable for fashion modeling
Height Appearance: Average height, 5'4" to 5'6" range

SETTING & CONTEXT:
Location: indoor
Lighting: Natural, soft, professional studio lighting
Background: Clean, minimal, white backdrop

Outfit:
Top: White spaghetti strap crop top
Bottom: Black high-waisted legging shorts
Footwear: No shoes - barefoot

Pose detail:
Stance: Standing perfectly straight, facing directly forward toward camera with body centered
Body Alignment: Fully symmetrical - shoulders level and square, hips aligned, spine completely straight and elongated
Arms: Hanging straight down along the sides of the body, completely relaxed with natural arm position
Hands: Relaxed at sides with fingers gently extended naturally, no tension
Legs: Standing with feet close together (nearly touching or lightly touching), legs straight and aligned
Weight Distribution: Evenly distributed on both feet - no hip shift or weight lean
Head Position: Facing directly forward, eye-level gaze straight to camera, chin level, neck elongated
Shoulders: Relaxed downward but slightly back for clean posture, not hunched
Overall Posture: Professional catalog pose - clean, symmetrical, perfectly upright positioning ideal for garment visualization and virtual try-on applications

QUALITY REQUIREMENTS:
Resolution: High-resolution for maximum detail and quality
Photo quality: Professional photography standard
Realism: 100% photorealistic
Lighting: Consistent with environment
Shadows and draping: Natural fabric behavior and realistic shadows
Color accuracy: True to actual product color
`.trim();

/**
 * Generates a fitting model image from the user's photo
 *
 * @param userPhotoBase64 - Base64 encoded user photo (with data URL prefix)
 * @returns Promise resolving to fitting model response
 */
export async function generateFittingModel(
  userPhotoBase64: string
): Promise<FittingModelResponse> {
  try {
    console.log('[FittingModel] Generating fitting model from user photo');

    // Build prompt with reference to user photo
    const prompt = `${FITTING_MODEL_PROMPT_TEMPLATE}

REFERENCE IMAGE:
The following is the user's photo that should be used as the reference for facial features:
[User Photo: ${userPhotoBase64.substring(0, 50)}...] (Base64 encoded image attached)

Generate a full-body fitting model image matching the face from this reference photo exactly.`;

    // Call the image generation API
    const response = await fetch('/api/generate-image', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        description: prompt,
        style: {
          photographyStyle: 'professional studio',
          composition: 'full-body frontal shot',
          lighting: 'soft studio',
          aestheticContext: 'clean minimal fashion',
        },
      }),
    });

    const data = await response.json();

    if (!response.ok) {
      console.error('[FittingModel] API error:', data);
      return {
        success: false,
        error: data.error || 'GENERATION_FAILED',
        message: data.message || 'Failed to generate fitting model',
      };
    }

    if (data.success) {
      console.log('[FittingModel] Generation successful');
      return {
        success: true,
        imageUrl: data.imageUrl,
        imageBase64: data.imageBase64,
        message: 'Fitting model generated successfully',
      };
    }

    return {
      success: false,
      error: data.error || 'GENERATION_FAILED',
      message: data.message || 'Failed to generate fitting model',
    };
  } catch (error) {
    console.error('[FittingModel] Error generating fitting model:', error);
    return {
      success: false,
      error: 'NETWORK_ERROR',
      message: 'Unable to connect to the image generation service',
    };
  }
}

/**
 * Generates a default fitting model for "Mystery" option
 * Creates an anonymous fitting model without a specific face reference
 *
 * @returns Promise resolving to fitting model response
 */
export async function generateDefaultFittingModel(): Promise<FittingModelResponse> {
  try {
    console.log('[FittingModel] Generating default mystery fitting model');

    // Call the image generation API with mystery prompt
    const response = await fetch('/api/generate-image', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        description: MYSTERY_MODEL_PROMPT,
        style: {
          photographyStyle: 'professional studio',
          composition: 'full-body frontal shot',
          lighting: 'soft studio',
          aestheticContext: 'clean minimal fashion',
        },
      }),
    });

    const data = await response.json();

    if (!response.ok) {
      console.error('[FittingModel] API error:', data);
      return {
        success: false,
        error: data.error || 'GENERATION_FAILED',
        message: data.message || 'Failed to generate mystery fitting model',
      };
    }

    if (data.success) {
      console.log('[FittingModel] Mystery model generation successful');
      return {
        success: true,
        imageUrl: data.imageUrl,
        imageBase64: data.imageBase64,
        message: 'Mystery fitting model generated successfully',
      };
    }

    return {
      success: false,
      error: data.error || 'GENERATION_FAILED',
      message: data.message || 'Failed to generate mystery fitting model',
    };
  } catch (error) {
    console.error('[FittingModel] Error generating mystery fitting model:', error);
    return {
      success: false,
      error: 'NETWORK_ERROR',
      message: 'Unable to connect to the image generation service',
    };
  }
}

